<?php ob_start(); ?><h1><?= e(t('Analyze file')) ?></h1><p class="muted"><?= e(t('Upload a suspicious file (or paste its content) to check it against every enabled signature and see if it has already been seen anywhere on this server — without waiting for a scan.')) ?></p>
<?php if($error): ?><div class="card"><p style="color:#fca5a5"><?= e($error) ?></p></div><?php endif ?>
<div class="card"><form method="post" action="/signatures/analyze" enctype="multipart/form-data"><p><input class="input" name="filename" placeholder="<?= e(t('Filename (optional, helps match by extension)')) ?>" value="<?= e($result['filename'] ?? '') ?>"></p><p><input type="file" name="file"></p><p class="muted"><?= e(t('...or paste raw content instead of uploading:')) ?></p><p><textarea class="input" name="content" rows="10" cols="100" placeholder="<?php echo '<?php ...'; ?>"></textarea></p><button class="btn"><?= e(t('Analyze')) ?></button></form></div>
<?php if($result): ?><div class="card"><h2><?= e(t('Result')) ?></h2><p><b><?= e(t('Filename:')) ?></b> <?= e($result['filename']) ?> <b><?= e(t('Size:')) ?></b> <?= e($result['size']) ?> <?= e(t('bytes')) ?></p><p><b>SHA256:</b> <code><?= e($result['sha256']) ?></code></p>
<?php if($result['matches']): ?><h3><?= e(t('Matched signatures')) ?></h3><table><tr><th><?= e(t('Name')) ?></th><th><?= e(t('Risk')) ?></th><th><?= e(t('Source')) ?></th></tr><?php foreach($result['matches'] as $m): $sig=$m['signature']; ?><tr><td><?= isset($sig['id']) && $sig['id'] !== null ? '<a href="/signatures/'.e($sig['id']).'">'.e($sig['name']).'</a>' : e($sig['name']) ?></td><td><span class="badge <?= e($sig['risk']) ?>"><?= e(t($sig['risk'])) ?></span></td><td><?= e($sig['source'] ?? '') ?></td></tr><?php endforeach ?></table><?php else: ?><p class="muted"><?= e(t('No existing signature matched this file.')) ?></p><p><a class="btn" href="/signatures/create-from-hash?sha256=<?= e($result['sha256']) ?>&filename=<?= urlencode($result['filename']) ?>"><?= e(t('Create signature from this file')) ?></a></p><?php endif ?>
<h3><?= e(t('Same file elsewhere')) ?></h3><?php if($result['elsewhere']): ?><table><tr><th><?= e(t('User')) ?></th><th><?= e(t('Site')) ?></th><th><?= e(t('Path')) ?></th><th><?= e(t('Status')) ?></th><th><?= e(t('Last seen')) ?></th></tr><?php foreach($result['elsewhere'] as $o): ?><tr><td><?= e($o['user_name'] ?? '') ?></td><td><?= e($o['site_name'] ?? '') ?></td><td><code><?= e($o['path']) ?></code></td><td><?= $o['is_missing'] ? e(t('deleted')) : e(t('present')) ?></td><td><?= e($o['last_seen_at']) ?></td></tr><?php endforeach ?></table><?php else: ?><p class="muted"><?= e(t('Not found on this server (not scanned, or was never hashed).')) ?></p><?php endif ?>
<h3><?= e(t('Preview')) ?></h3><pre><?= e($result['preview']) ?></pre></div><?php endif ?>
<?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
